using System.Windows;
using System.Windows.Media;
using System.Windows.Media.Imaging;

namespace Mesura.App;

/// <summary>
/// Mesura's identity in one place: the icon used by the exe (ApplicationIcon), the window and the tray all come from
/// <c>Assets/mesura.ico</c>, and the mark drawn inside the window from <c>Assets/mesura-mark.png</c>; both are generated by
/// <c>tools/make-branding.ps1</c> from one geometry, so they can't drift apart.
/// </summary>
public static class Branding
{
    public const string Name = "Mesura";

    private static readonly Uri IconUri = new("pack://application:,,,/Assets/mesura.ico", UriKind.Absolute);

    private static readonly Uri MarkUri = new("pack://application:,,,/Assets/mesura-mark.png", UriKind.Absolute);

    /// <summary>The version without the commit suffix ("0.2.0"), for the top strip.</summary>
    public static string ShortVersion { get; } = (System.Reflection.Assembly.GetExecutingAssembly()
        .GetCustomAttributes(typeof(System.Reflection.AssemblyInformationalVersionAttribute), false)
        .OfType<System.Reflection.AssemblyInformationalVersionAttribute>().FirstOrDefault()?.InformationalVersion ?? "0.0.0").Split('+')[0];

    /// <summary>The mark shown inside the window (the sidebar, Settings), a 256 px image scaled down with high quality.</summary>
    public static ImageSource Mark { get; } = CreateMark();

    private static BitmapImage CreateMark()
    {
        var image = new BitmapImage();
        image.BeginInit();
        image.UriSource = MarkUri;
        image.CacheOption = BitmapCacheOption.OnLoad;
        image.EndInit();
        image.Freeze();
        return image;
    }

    /// <summary>The window and taskbar icon.</summary>
    public static ImageSource WindowIcon { get; } = BitmapFrame.Create(IconUri);

    /// <summary>The tray icon, at the size Windows asks for in the notification area.</summary>
    public static System.Drawing.Icon CreateTrayIcon()
    {
        var info = Application.GetResourceStream(IconUri)
            ?? throw new InvalidOperationException("The Mesura icon resource is missing from this build.");
        using var stream = info.Stream;
        var small = System.Windows.Forms.SystemInformation.SmallIconSize;
        return new System.Drawing.Icon(stream, small.Width, small.Height);
    }
}
